from flask import Flask, request, jsonify, abort
from dataclasses import dataclass, field, asdict
from typing import Dict, List, Optional
from uuid import uuid4
from datetime import datetime

app = Flask(__name__)

@dataclass
class StoreSettings:
    name: str = ""
    contact_details: str = ""
    currency: str = "USD"
    tax_settings: str = "standard"
    shipping_methods: List[str] = field(default_factory=lambda: ["standard"])
    payment_options: List[str] = field(default_factory=lambda: ["card"])
    legal_details: str = ""
    live: bool = False

@dataclass
class Product:
    id: str
    name: str
    price: float
    stock: int
    active: bool = True
    low_stock_threshold: int = 5
    category: str = ""

@dataclass
class Customer:
    id: str
    name: str
    email: str
    password: str
    status: str = "active"
    address: dict = field(default_factory=dict)
    orders: List[str] = field(default_factory=list)

@dataclass
class Order:
    id: str
    customer_id: str
    items: List[dict]
    shipping_method: str
    payment_method: str
    status: str = "new"
    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    total: float = 0.0
    shipping_address: dict = field(default_factory=dict)

state = {
    "settings": StoreSettings(),
    "products": {},
    "customers": {},
    "carts": {},
    "orders": {},
    "staff": {"owner": {"role": "owner"}, "sales": {"role": "sales"}},
}


def require_setup():
    s = state["settings"]
    if not (s.name and s.contact_details and s.currency and s.shipping_methods and s.payment_options):
        abort(400, description="core settings incomplete")


def validate_customer_data(data):
    for field_name in ["name", "email", "password"]:
        if not data.get(field_name):
            abort(400, description="missing customer details")
    if any(c.email == data["email"] for c in state["customers"].values()):
        abort(409, description="duplicate customer")


def validate_address(address):
    required = ["name", "street_address", "city", "postal_code", "country"]
    if not all(address.get(k) for k in required):
        abort(400, description="incomplete shipping address")
    if not (address.get("phone") or address.get("email")):
        abort(400, description="missing shipping contact")


def cart_for(customer_id):
    return state["carts"].setdefault(customer_id, [])


@app.get("/health")
def health():
    return {"ok": True}


@app.post("/setup")
def setup():
    data = request.get_json(force=True)
    s = state["settings"]
    s.name = data.get("name", s.name)
    s.contact_details = data.get("contact_details", s.contact_details)
    s.currency = data.get("currency", s.currency)
    s.tax_settings = data.get("tax_settings", s.tax_settings)
    s.shipping_methods = data.get("shipping_methods", s.shipping_methods)
    s.payment_options = data.get("payment_options", s.payment_options)
    s.legal_details = data.get("legal_details", s.legal_details)
    if s.name and s.contact_details and s.currency:
        s.live = True
    return jsonify(asdict(s))


@app.get("/settings")
def get_settings():
    return jsonify(asdict(state["settings"]))


@app.post("/products")
def add_product():
    data = request.get_json(force=True)
    role = data.get("role")
    if role not in {"owner", "sales"}:
        abort(403)
    if role == "sales" and not data.get("active", True):
        abort(403)
    p = Product(id=str(uuid4()), name=data["name"], price=float(data["price"]), stock=int(data.get("stock", 0)), active=bool(data.get("active", True)), low_stock_threshold=int(data.get("low_stock_threshold", 5)), category=data.get("category", ""))
    state["products"][p.id] = p
    return jsonify(asdict(p)), 201


@app.patch("/products/<pid>")
def edit_product(pid):
    data = request.get_json(force=True)
    role = data.get("role")
    p = state["products"].get(pid)
    if not p:
        abort(404)
    if not p.active and role == "sales":
        abort(403)
    for k in ["name", "price", "stock", "active", "low_stock_threshold", "category"]:
        if k in data:
            setattr(p, k, data[k])
    return jsonify(asdict(p))


@app.post("/customers")
def create_customer():
    data = request.get_json(force=True)
    validate_customer_data(data)
    c = Customer(id=str(uuid4()), name=data["name"], email=data["email"], password=data["password"], status=data.get("status", "active"), address=data.get("address", {}))
    state["customers"][c.id] = c
    return jsonify({"id": c.id, "status": c.status}), 201


@app.get("/products")
def list_products():
    return jsonify([asdict(p) for p in state["products"].values() if p.active])


@app.post("/cart/<customer_id>/items")
def add_to_cart(customer_id):
    data = request.get_json(force=True)
    p = state["products"].get(data["product_id"])
    if not p or not p.active:
        abort(404)
    qty = int(data.get("qty", 1))
    if qty > p.stock:
        abort(400, description="insufficient stock")
    cart_for(customer_id).append({"product_id": p.id, "qty": qty})
    return jsonify(cart_for(customer_id))


@app.get("/cart/<customer_id>")
def get_cart(customer_id):
    return jsonify(cart_for(customer_id))


@app.post("/orders")
def place_order():
    data = request.get_json(force=True)
    customer_id = data["customer_id"]
    customer = state["customers"].get(customer_id)
    if not customer or customer.status != "active":
        abort(403)
    validate_address(data.get("shipping_address", {}))
    items = cart_for(customer_id)
    if not items:
        abort(400, description="empty cart")
    shipping_method = data.get("shipping_method", "standard")
    if shipping_method not in state["settings"].shipping_methods:
        abort(400, description="shipping method unavailable")
    payment_method = data.get("payment_method", "card")
    if payment_method not in state["settings"].payment_options:
        abort(400, description="payment method unavailable")
    total = 0.0
    for item in items:
        p = state["products"].get(item["product_id"])
        if not p or p.stock < item["qty"]:
            abort(400, description="item unavailable")
        total += p.price * item["qty"]
    order = Order(id=str(uuid4()), customer_id=customer_id, items=items.copy(), shipping_method=shipping_method, payment_method=payment_method, total=total, shipping_address=data["shipping_address"], status="paid" if payment_method else "new")
    for item in items:
        state["products"][item["product_id"]].stock -= item["qty"]
    state["orders"][order.id] = order
    customer.orders.append(order.id)
    state["carts"][customer_id] = []
    return jsonify(asdict(order)), 201


@app.patch("/orders/<oid>")
def update_order(oid):
    data = request.get_json(force=True)
    order = state["orders"].get(oid)
    if not order:
        abort(404)
    role = data.get("role")
    if data.get("status"):
        if role not in {"owner", "sales"}:
            abort(403)
        order.status = data["status"]
    return jsonify(asdict(order))


@app.get("/low-stock")
def low_stock():
    warnings = []
    for p in state["products"].values():
        if p.stock <= p.low_stock_threshold:
            warnings.append({"product_id": p.id, "name": p.name, "stock": p.stock})
    return jsonify(warnings)


@app.get("/")
def index():
    return jsonify({"service": "GAMMA-J Web Store", "live": state["settings"].live})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000)
EOF

